// The API catalog: the names from apis.txt, as a C array.
//
// Generated by generator.cpp at build time; do not edit by hand, and do not commit
// a copy. It exists so `--list` and the unknown-name check read the same list the
// symlinks are created from, with no second source of truth.
//
// The name is derived from the file, matching `_binary_*_start` naming: the array
// is `kApiNames` and the count is `kApiNameCount`.

#ifndef VYZORIX_ANDROID_BIN_API_CATALOG_H
#define VYZORIX_ANDROID_BIN_API_CATALOG_H

#include <cstddef>

extern const char *const kApiNames[];
extern const std::size_t kApiNameCount;

/** True when `name` is one of the catalog entries. */
bool IsKnownApi(const char *name);

#endif // VYZORIX_ANDROID_BIN_API_CATALOG_H
